namespace Spatie\Permission\Traits;

use Illuminate\Database\Eloquent\Collection as EloquentCollection;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Arr;
use Illuminate\Support\Collection;
use Spatie\Permission\PermissionRegistrar;
use Spatie\Permission\Support\Config;

trait HasAssignedModels
{
    /**
     * Replace all existing model associations for this role with the given set.
     *
     * An empty array/collection removes every association. Inputs are
     * deduplicated so no duplicate pivot records are created.
     *
     * @param  array|Collection|Model|int|string  $models
     */
    public function syncModels($models, ?string $modelClass = null): static
    {
        $models = $this->collectAssignedModels($models, $modelClass);

        $this->getConnection()
            ->table(Config::modelHasRolesTable())
            ->where(app(PermissionRegistrar::class)->pivotRole, $this->getKey())
            ->delete();

        $this->assignModelRecords($models);

        return $this;
    }

    /**
     * Assign this role to the given models without removing existing assignments.
     *
     * Idempotent — models that already have the role are not re-inserted — and
     * inputs are deduplicated.
     *
     * @param  array|Collection|Model|int|string  $models
     */
    public function assignToModels($models, ?string $modelClass = null): static
    {
        $this->assignModelRecords($this->collectAssignedModels($models, $modelClass));

        return $this;
    }

    /**
     * Remove this role from the given models, leaving all other assignments intact.
     *
     * Safe to call for models that do not currently have the role.
     *
     * @param  array|Collection|Model|int|string  $models
     */
    public function removeFromModels($models, ?string $modelClass = null): static
    {
        foreach ($this->groupModelsByClass($this->collectAssignedModels($models, $modelClass)) as $class => $keys) {
            $this->assignedModelsRelation($class)->detach($keys);
        }

        return $this;
    }

    /**
     * Attach the given models to this role, deduplicating and without detaching.
     */
    protected function assignModelRecords(EloquentCollection $models): void
    {
        foreach ($this->groupModelsByClass($models) as $class => $keys) {
            $this->assignedModelsRelation($class)->syncWithoutDetaching($keys);
        }
    }

    /**
     * Build the morph relation that ties this role to models of the given class.
     */
    protected function assignedModelsRelation(string $class)
    {
        return $this->morphedByMany(
            $class,
            'model',
            Config::modelHasRolesTable(),
            app(PermissionRegistrar::class)->pivotRole,
            Config::morphKey()
        );
    }

    /**
     * Group the resolved models by their class, keyed by primary key to
     * deduplicate models supplied more than once.
     *
     * @return array<class-string, array<int|string, int|string>>
     */
    protected function groupModelsByClass(EloquentCollection $models): array
    {
        $grouped = [];

        foreach ($models as $model) {
            $grouped[$model::class][(string) $model->getKey()] = $model->getKey();
        }

        return $grouped;
    }

    /**
     * Normalize the supplied models/IDs into a collection of model instances.
     *
     * Model instances are used as-is; raw IDs are resolved against the given
     * class, falling back to the `permission.models.default_model` config value.
     *
     * @param  array|Collection|Model|int|string  $models
     */
    protected function collectAssignedModels($models, ?string $modelClass = null): EloquentCollection
    {
        if ($models instanceof Collection) {
            $models = $models->all();
        } elseif ($models instanceof Model) {
            $models = [$models];
        } else {
            $models = Arr::wrap($models);
        }

        $resolved = new EloquentCollection;
        $idsByClass = [];

        foreach ($models as $model) {
            if ($model instanceof Model) {
                $resolved->push($model);

                continue;
            }

            if ($model === null || $model === '') {
                continue;
            }

            $class = $modelClass ?? config('permission.models.default_model');

            if (! $class) {
                continue;
            }

            $idsByClass[$class][] = $model;
        }

        foreach ($idsByClass as $class => $ids) {
            $instance = new $class;

            $resolved = $resolved->merge(
                $class::whereIn($instance->getKeyName(), array_unique($ids))->get()
            );
        }

        return $resolved;
    }
}
